# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def make_student(last, first, section, email):
    return Student("id", last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        rows = contact_rows([
            make_student("Thistle", "Bram", "A", "b@x.org"),
            make_student("Ash", "Cy", "B", "c@x.org")
        ])
        self.assertEqual(rows, [
            "Ash, Cy        B  c@x.org",
            "Thistle, Bram  A  b@x.org"
        ])

    def test_missing_email_names_student(self):
        nomail = make_student("Ash", "Cy", "A", None)
        with self.assertRaises(ProjectError) as caught:
            contact_rows([nomail])
        self.assertIn("Ash, Cy", str(caught.exception))

    def test_blank_email_is_missing(self):
        blank = make_student("Ash", "Cy", "A", "  ")
        with self.assertRaises(ProjectError):
            contact_rows([blank])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
